WITH scores AS (
 SELECT first_player AS player_id,first_score AS score FROM Matches
 UNION ALL SELECT second_player,second_score FROM Matches
), totals AS (
 SELECT p.group_id,p.player_id,COALESCE(SUM(s.score),0) AS total
 FROM Players p LEFT JOIN scores s ON p.player_id=s.player_id GROUP BY p.group_id,p.player_id
), ranked AS (
 SELECT *,ROW_NUMBER() OVER(PARTITION BY group_id ORDER BY total DESC,player_id) AS ranking FROM totals
) SELECT group_id,player_id FROM ranked WHERE ranking=1

WITH daily AS (
 SELECT user_id,action_date,MIN(action) AS action FROM activity GROUP BY user_id,action_date HAVING COUNT(*)=1
), groups AS (
 SELECT *,julianday(action_date)-row_number() OVER(PARTITION BY user_id,action ORDER BY action_date) AS grp FROM daily
), streaks AS (
 SELECT user_id,action,COUNT(*) AS streak_length,MIN(action_date) AS start_date,MAX(action_date) AS end_date
 FROM groups GROUP BY user_id,action,grp HAVING COUNT(*)>=5
), ranked AS (
 SELECT *,ROW_NUMBER() OVER(PARTITION BY user_id ORDER BY streak_length DESC,start_date,action) AS rn FROM streaks
)
SELECT user_id,action,streak_length,start_date,end_date FROM ranked WHERE rn=1 ORDER BY streak_length DESC,user_id

WITH ordered AS (
 SELECT *,LAG(session_date) OVER(PARTITION BY student_id ORDER BY session_date,session_id) AS previous_date FROM study_sessions
), grouped AS (
 SELECT *,SUM(CASE WHEN previous_date IS NULL OR julianday(session_date)-julianday(previous_date)>2 THEN 1 ELSE 0 END)
 OVER(PARTITION BY student_id ORDER BY session_date,session_id) AS grp FROM ordered
), positions AS (
 SELECT *,ROW_NUMBER() OVER(PARTITION BY student_id,grp ORDER BY session_date,session_id) AS rn FROM grouped
), summaries AS (
 SELECT student_id,grp,COUNT(DISTINCT subject) AS cycle_length,COUNT(*) AS n,SUM(hours_studied) AS hours FROM positions GROUP BY student_id,grp
), valid AS (
 SELECT *,ROW_NUMBER() OVER(PARTITION BY student_id ORDER BY cycle_length DESC,hours DESC,grp) AS choice FROM summaries g
 WHERE cycle_length>=3 AND n>=2*cycle_length AND NOT EXISTS (
 SELECT 1 FROM positions a JOIN positions b ON a.student_id=b.student_id AND a.grp=b.grp
 AND b.rn=((a.rn-1)%g.cycle_length)+1
 WHERE a.student_id=g.student_id AND a.grp=g.grp AND a.subject<>b.subject
 )
)
SELECT s.student_id,s.student_name,s.major,v.cycle_length,v.hours AS total_study_hours
FROM valid v JOIN students s USING(student_id) WHERE choice=1 ORDER BY cycle_length DESC,total_study_hours DESC
